insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-3a', 'world-3', 'ghosts-in-the-switch', '3A - Ghosts in the Switch', 'A hospital floor loses connectivity while a device impersonates multiple machines at Layer 2.', 1);
insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-3a-1', 'campaign-3a', 'foundations', 'Foundations', 'Switch tables, ARP, VLANs and spanning tree, learned as tools for reading local-network trust.', 1),
  ('operation-3a-2', 'campaign-3a', 'investigation', 'Investigation', 'Correlate the evidence and isolate the rogue device.', 2);
insert into public.missions (
insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-w3-01', 1, 'zayn', 'Mercy General''s third floor keeps dropping off the network, and it''s not simple congestion. Something on that segment is impersonating other machines.'),
  ('mission-w3-01', 2, 'zayn', 'Time to go local. Everything past this point happens inside one switch''s world -- MAC addresses, frames, and trust that was never supposed to be optional.'),
  ('mission-w3-02', 1, 'zayn', 'A switch learns which MAC address lives behind which port by watching traffic. When one MAC starts showing up behind multiple ports, something''s lying.'),
  ('mission-w3-03', 1, 'zayn', 'ARP maps IP addresses to MAC addresses. It''s also completely unauthenticated -- anything on the segment can claim to be anyone.'),
  ('mission-w3-04', 1, 'zayn', 'Segmentation is supposed to keep the nurses'' station, the medical devices, and the guest network from ever touching each other. Let''s confirm it actually does.'),
  ('mission-w3-05', 1, 'zayn', 'Someone bridged two switch ports together that should never be connected, and now frames are looping the segment into the ground. Spanning tree exists to stop exactly this.'),
  ('mission-w3-06', 1, 'zayn', 'Everything we''ve pulled -- the flapping MAC, the spoofed gateway, all of it -- traces back to one physical port. Find it, and pull it without taking the floor down.'),
  ('mission-w3-06', 2, 'zayn', 'Isolated. Floor''s still up, nurses'' station never even noticed.'),
  ('mission-w3-06', 3, 'byte', 'The device transmitted continuously while connected. One detail stands out: a 256-second interval, every frame empty except for six bytes.'),
  ('mission-w3-06', 4, 'zayn', 'Read them.'),
  ('mission-w3-06', 5, 'byte', 'SX-7. Same string. This is not the first time this signature has shown up, and it will not be the last.'),
  ('mission-w3-06', 6, 'zayn', 'It also knew addresses outside this subnet existed at all. That''s not something a purely local device should know. We need to understand how it would even reach them -- that''s IP addressing and routing, not switching.');
insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-w3-01-o1', 'mission-w3-01', 1, 'Acknowledge the briefing', 'Confirm you''re ready to work at the local-network level.'),
  ('mission-w3-02-o1', 'mission-w3-02', 1, 'Spot the flapping MAC', 'Identify the entries that prove a MAC address is relearning on a different port.'),
  ('mission-w3-03-o1', 'mission-w3-03', 1, 'Spot the ARP spoof', 'Find the evidence that the gateway''s address is being hijacked at Layer 2.'),
  ('mission-w3-04-o1', 'mission-w3-04', 1, 'Match VLAN to purpose', 'Assign each VLAN to the segment it''s actually supposed to serve.'),
  ('mission-w3-05-o1', 'mission-w3-05', 1, 'Order the port states', 'Order the states a port passes through from loop-safe to fully active.'),
  ('mission-w3-06-o1', 'mission-w3-06', 1, 'Correlate the evidence', 'Identify the port that is the rogue device''s actual physical origin.'),
  ('mission-w3-06-o2', 'mission-w3-06', 2, 'Confirm the identity', 'State what the rogue device is actually doing on this segment.'),
  ('mission-w3-06-o3', 'mission-w3-06', 3, 'Isolate and report', 'Confirm the port to isolate and summarize the finding.');
insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-w3-01-o1-c1', 'mission-w3-01-o1', 1, 'story_dialogue', 'Confirm you''re ready to continue.', '{"lines":[{"characterId":"zayn","text":"Everything on this floor lives inside one switch''s world right now. Ready to look?"}]}'::jsonb, '{"acknowledged":true}'::jsonb),
  ('mission-w3-02-o1-c1', 'mission-w3-02-o1', 1, 'investigation', 'Which entries show the same MAC address rapidly relearning on a different port?', '{"evidence":[{"id":"e1","label":"MAC 00:1A:2B:3C:4D:5E -- Port 3","detail":"Consistently seen on port 3 for the past six hours"},{"id":"e2","label":"MAC 00:1A:2B:3C:4D:5E -- Port 7","detail":"Same MAC address, now also learned on port 7, two minutes later"},{"id":"e3","label":"MAC 00:1A:2B:3C:4D:5E -- Port 3 (again)","detail":"Same MAC re-learned back on port 3, ninety seconds after appearing on port 7"},{"id":"e4","label":"MAC 88:CC:11:22:33:44 -- Port 5","detail":"A different device, stable on port 5 the entire period"}],"question":"Which entries show the same MAC address rapidly relearning on a different port?"}'::jsonb, '{"requiredEvidenceIds":["e2","e3"]}'::jsonb),
  ('mission-w3-03-o1-c1', 'mission-w3-03-o1', 1, 'investigation', 'Which entries show evidence that the gateway''s IP address is being hijacked at Layer 2?', '{"evidence":[{"id":"a1","label":"10.20.4.1 -> 00:1A:2B:3C:4D:5E","detail":"The nurses'' station gateway, resolved consistently for weeks"},{"id":"a2","label":"10.20.4.1 -> 9A:FF:00:11:22:33","detail":"The same gateway IP, now also resolving to a second, different MAC"},{"id":"a3","label":"10.20.4.15 -> 88:CC:11:22:33:44","detail":"A workstation, stable resolution, unchanged for days"},{"id":"a4","label":"Gratuitous ARP broadcast for 10.20.4.1","detail":"Unsolicited announcement claiming ownership of the gateway address, sent from 9A:FF:00:11:22:33"}],"question":"Which entries show evidence that the gateway''s IP address is being hijacked at Layer 2?"}'::jsonb, '{"requiredEvidenceIds":["a2","a4"]}'::jsonb),
  ('mission-w3-04-o1-c1', 'mission-w3-04-o1', 1, 'drag_and_drop', 'Match each VLAN to the segment it serves.', '{"items":[{"id":"vlan10","text":"VLAN 10 -- ports connect nurses'' station PCs"},{"id":"vlan20","text":"VLAN 20 -- ports connect infusion pumps and monitors"},{"id":"vlan30","text":"VLAN 30 -- ports serve the visitor Wi-Fi access points"},{"id":"vlan99","text":"VLAN 99 -- carries only switch-to-switch management traffic"}],"targets":[{"id":"clinical","label":"Clinical workstations"},{"id":"devices","label":"Medical devices"},{"id":"guest","label":"Guest Wi-Fi"},{"id":"mgmt","label":"Network management"}]}'::jsonb, '{"correctMapping":{"vlan10":"clinical","vlan20":"devices","vlan30":"guest","vlan99":"mgmt"}}'::jsonb),
  ('mission-w3-05-o1-c1', 'mission-w3-05-o1', 1, 'interactive_diagram', 'Order the states a port passes through from disabled-for-loops to fully active.', '{"hotspots":[{"id":"blocking","label":"Blocking","explanation":"Receives BPDUs but does not forward frames -- the default safe state for a redundant link."},{"id":"listening","label":"Listening","explanation":"Begins participating in the spanning tree calculation, still not forwarding frames."},{"id":"learning","label":"Learning","explanation":"Starts building the MAC address table but still does not forward frames."},{"id":"forwarding","label":"Forwarding","explanation":"Fully active -- forwards frames normally."}],"task":"Order the states a port passes through from disabled-for-loops to fully active."}'::jsonb, '{"correctOrderIds":["blocking","listening","learning","forwarding"]}'::jsonb),
  ('mission-w3-06-o1-c1', 'mission-w3-06-o1', 1, 'investigation', 'Which port is the actual physical origin of the rogue device?', '{"evidence":[{"id":"p1","label":"Port 3","detail":"The flapping MAC''s original, long-standing port"},{"id":"p2","label":"Port 7","detail":"Where the flapping MAC and the ARP-spoofing MAC were both observed simultaneously"},{"id":"p3","label":"Port 12","detail":"Stable, unrelated printer traffic only"},{"id":"p4","label":"Port 7 uplink log","detail":"A device on this port was physically connected two hours before the first flapping event"}],"question":"Which port is the actual physical origin of the rogue device?"}'::jsonb, '{"requiredEvidenceIds":["p2","p4"]}'::jsonb),
  ('mission-w3-06-o2-c1', 'mission-w3-06-o2', 1, 'multiple_choice', 'Given everything gathered, what is the rogue device actually doing on this segment?', '{"question":"Given everything gathered, what is the rogue device actually doing on this segment?","options":[{"id":"a","text":"Nothing malicious -- likely a misconfigured legitimate switch creating a loop"},{"id":"b","text":"Impersonating the gateway via ARP spoofing while beaconing on a fixed interval"},{"id":"c","text":"A failing network card causing random MAC table corruption"},{"id":"d","text":"A rogue DHCP server handing out bad addresses"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-w3-06-o3-c1', 'mission-w3-06-o3', 1, 'boss_encounter', 'Confirm the port to isolate and summarize the finding for the incident log.', '{"stages":[{"objectiveRef":"mission-w3-06-o1","label":"The physical origin"},{"objectiveRef":"mission-w3-06-o2","label":"The confirmed behavior"}],"task":"Confirm the port to isolate and summarize the finding for the incident log."}'::jsonb, '{"requiredObjectiveIds":["mission-w3-06-o1","mission-w3-06-o2"],"allCorrect":true}'::jsonb);
insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-w3-01-o1-c1', 'orientation', 'There''s nothing to solve here -- just confirm you''re ready to continue.', 0, 1),
  ('mission-w3-02-o1-c1', 'orientation', 'One MAC address appears more than once in this table, on different ports.', 10, 1),
  ('mission-w3-02-o1-c1', 'concept', 'A legitimate device doesn''t usually jump between switch ports every couple of minutes.', 20, 2),
  ('mission-w3-02-o1-c1', 'solution', 'e2 and e3 show the same MAC relearning on a different port within minutes -- that''s the flapping. e1 is just the original baseline and e4 is a stable, unrelated device.', 30, 3),
  ('mission-w3-03-o1-c1', 'orientation', 'One of these four IP-to-MAC pairs should never change, and it just did.', 10, 1),
  ('mission-w3-03-o1-c1', 'concept', 'A gratuitous ARP is a device announcing an address mapping nobody asked about -- legitimate uses exist, but so does this one.', 20, 2),
  ('mission-w3-03-o1-c1', 'tool_direction', 'Compare the gateway''s long-standing MAC against what it resolves to now, then check who''s broadcasting the claim.', 30, 3),
  ('mission-w3-03-o1-c1', 'solution', 'The gateway now also resolves to a second MAC (a2), and that same MAC just broadcast an unsolicited claim to own the gateway address (a4) -- classic ARP spoofing. a1 and a3 are stable, legitimate baselines.', 40, 4),
  ('mission-w3-04-o1-c1', 'orientation', 'Each VLAN''s description already tells you exactly what it connects to -- match the description, not the number.', 10, 1),
  ('mission-w3-04-o1-c1', 'solution', 'VLAN 10 (nurses'' station PCs) is clinical, VLAN 20 (pumps/monitors) is medical devices, VLAN 30 (visitor Wi-Fi) is guest, and VLAN 99 (switch-to-switch only) is management.', 20, 2),
  ('mission-w3-05-o1-c1', 'orientation', 'The state that exists purely to prevent a loop has to come first.', 10, 1),
  ('mission-w3-05-o1-c1', 'concept', 'A port has to know its neighbors before it starts remembering MAC addresses, and both have to happen before it moves real traffic.', 20, 2),
  ('mission-w3-05-o1-c1', 'solution', 'Blocking -> listening -> learning -> forwarding is the sequence a port takes as spanning tree clears it to carry real traffic.', 30, 3),
  ('mission-w3-06-o1-c1', 'orientation', 'The port that''s merely where the original device was learned isn''t necessarily where the rogue device actually is.', 15, 1),
  ('mission-w3-06-o1-c1', 'concept', 'Look for the port where both anomalies converge, then check when a new device was actually connected there.', 25, 2),
  ('mission-w3-06-o1-c1', 'tool_direction', 'Cross-reference the uplink log''s timestamp against when the flapping first started.', 35, 3),
  ('mission-w3-06-o1-c1', 'solution', 'Port 7 is where both the flapping MAC and the spoofing MAC converge, and its uplink log shows a new device connected right before the anomalies started -- ports 3 and 12 are the original learned location and unrelated traffic.', 45, 4),
  ('mission-w3-06-o2-c1', 'orientation', 'Rule out explanations that don''t account for both the ARP spoofing and the fixed-interval beacon.', 15, 1),
  ('mission-w3-06-o2-c1', 'solution', 'Only option b accounts for both the deliberate gateway impersonation and the beaconing pattern -- the others explain at most one symptom.', 25, 2),
  ('mission-w3-06-o3-c1', 'orientation', 'You''ve already gathered everything you need -- this is about combining the two findings.', 20, 1),
  ('mission-w3-06-o3-c1', 'concept', 'The report needs both the physical location and the confirmed behavior to be actionable.', 30, 2),
  ('mission-w3-06-o3-c1', 'tool_direction', 'State the port first, then what was actually happening on it.', 40, 3),
  ('mission-w3-06-o3-c1', 'near_solution', 'Port 7, running ARP spoofing plus a fixed-interval beacon -- that''s the whole finding.', 50, 4),
  ('mission-w3-06-o3-c1', 'solution', 'Port 7 carries a device that impersonated the gateway via ARP spoofing while beaconing on a fixed 256-second interval -- isolate that port; the rest of the floor''s traffic is unaffected.', 60, 5);
